CREATE TABLE AppUsers(Id INT IDENTITY PRIMARY KEY,UserName NVARCHAR(100) NOT NULL UNIQUE,DisplayName NVARCHAR(200) NOT NULL,EmployeeId INT NULL,IsAdmin BIT NOT NULL DEFAULT 0,IsActive BIT NOT NULL DEFAULT 1,PasswordHash NVARCHAR(256) NOT NULL);
CREATE TABLE OrgUnits(Id INT IDENTITY PRIMARY KEY,Code NVARCHAR(50) NOT NULL UNIQUE,Title NVARCHAR(200) NOT NULL,ParentId INT NULL,IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Positions(Id INT IDENTITY PRIMARY KEY,Code NVARCHAR(50) NOT NULL UNIQUE,Title NVARCHAR(200) NOT NULL,MaxScore DECIMAL(10,2) NOT NULL DEFAULT 100,IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Questions(Id INT IDENTITY PRIMARY KEY,PositionId INT NOT NULL,Text NVARCHAR(1000) NOT NULL,MaxScore DECIMAL(10,2) NOT NULL,SortOrder INT NOT NULL DEFAULT 1,IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Employees(Id INT IDENTITY PRIMARY KEY,PersonnelNo NVARCHAR(50) NOT NULL UNIQUE,NationalNo NVARCHAR(20) NULL,FullName NVARCHAR(200) NOT NULL,Mobile NVARCHAR(30) NULL,PositionId INT NOT NULL,UnitId INT NOT NULL,IsEvaluator BIT NOT NULL DEFAULT 0,SupervisorId INT NULL,IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE EvaluationPeriods(Id INT IDENTITY PRIMARY KEY,Title NVARCHAR(100) NOT NULL,StartJalali NVARCHAR(10) NOT NULL,EndJalali NVARCHAR(10) NOT NULL,StartAt DATETIME2 NOT NULL,EndAt DATETIME2 NOT NULL,IsOpen BIT NOT NULL DEFAULT 1,Description NVARCHAR(1000) NULL);
CREATE TABLE Evaluations(Id INT IDENTITY PRIMARY KEY,PeriodId INT NOT NULL,EmployeeId INT NOT NULL,EvaluatorId INT NOT NULL,OriginalEvaluatorId INT NOT NULL,CreatedAt DATETIME2 NOT NULL,UpdatedAt DATETIME2 NOT NULL,Status INT NOT NULL DEFAULT 0,CONSTRAINT UQ_Evaluation UNIQUE(PeriodId,EmployeeId));
CREATE TABLE EvaluationScores(Id INT IDENTITY PRIMARY KEY,EvaluationId INT NOT NULL,QuestionId INT NOT NULL,Score DECIMAL(10,2) NOT NULL,Comment NVARCHAR(1000) NULL,UpdatedAt DATETIME2 NOT NULL,CONSTRAINT UQ_EvaluationScore UNIQUE(EvaluationId,QuestionId));
CREATE TABLE EvaluationScoreHistory(Id BIGINT IDENTITY PRIMARY KEY,EvaluationId INT NOT NULL,QuestionId INT NOT NULL,OldScore DECIMAL(10,2) NOT NULL,NewScore DECIMAL(10,2) NOT NULL,ChangedBy INT NOT NULL,ChangedAt DATETIME2 NOT NULL,Reason NVARCHAR(500) NOT NULL);
CREATE TABLE EvaluatorChangeHistory(Id BIGINT IDENTITY PRIMARY KEY,EvaluationId INT NOT NULL,PreviousEvaluatorId INT NOT NULL,NewEvaluatorId INT NOT NULL,ChangedBy INT NOT NULL,ChangedAt DATETIME2 NOT NULL,Reason NVARCHAR(500) NOT NULL);
CREATE TABLE AuditLogs(Id BIGINT IDENTITY PRIMARY KEY,Action NVARCHAR(100) NOT NULL,Entity NVARCHAR(100) NOT NULL,EntityId NVARCHAR(100) NOT NULL,Details NVARCHAR(MAX) NULL,UserId INT NULL,CreatedAt DATETIME2 NOT NULL);
ALTER TABLE AppUsers ADD CONSTRAINT FK_AppUser_Employee FOREIGN KEY(EmployeeId) REFERENCES Employees(Id);
ALTER TABLE Employees ADD CONSTRAINT FK_Employee_Position FOREIGN KEY(PositionId) REFERENCES Positions(Id);ALTER TABLE Employees ADD CONSTRAINT FK_Employee_Unit FOREIGN KEY(UnitId) REFERENCES OrgUnits(Id);ALTER TABLE Employees ADD CONSTRAINT FK_Employee_Supervisor FOREIGN KEY(SupervisorId) REFERENCES Employees(Id);
ALTER TABLE Questions ADD CONSTRAINT FK_Question_Position FOREIGN KEY(PositionId) REFERENCES Positions(Id);ALTER TABLE OrgUnits ADD CONSTRAINT FK_OrgUnit_Parent FOREIGN KEY(ParentId) REFERENCES OrgUnits(Id);
ALTER TABLE Evaluations ADD CONSTRAINT FK_Evaluation_Period FOREIGN KEY(PeriodId) REFERENCES EvaluationPeriods(Id);ALTER TABLE Evaluations ADD CONSTRAINT FK_Evaluation_Employee FOREIGN KEY(EmployeeId) REFERENCES Employees(Id);ALTER TABLE Evaluations ADD CONSTRAINT FK_Evaluation_Evaluator FOREIGN KEY(EvaluatorId) REFERENCES Employees(Id);ALTER TABLE EvaluationScores ADD CONSTRAINT FK_Score_Evaluation FOREIGN KEY(EvaluationId) REFERENCES Evaluations(Id);ALTER TABLE EvaluationScores ADD CONSTRAINT FK_Score_Question FOREIGN KEY(QuestionId) REFERENCES Questions(Id);
ALTER TABLE EvaluationScoreHistory ADD CONSTRAINT FK_ScoreHistory_Evaluation FOREIGN KEY(EvaluationId) REFERENCES Evaluations(Id);ALTER TABLE EvaluationScoreHistory ADD CONSTRAINT FK_ScoreHistory_Question FOREIGN KEY(QuestionId) REFERENCES Questions(Id);ALTER TABLE EvaluationScoreHistory ADD CONSTRAINT FK_ScoreHistory_ChangedBy FOREIGN KEY(ChangedBy) REFERENCES Employees(Id);
ALTER TABLE EvaluatorChangeHistory ADD CONSTRAINT FK_EvaluatorHistory_Evaluation FOREIGN KEY(EvaluationId) REFERENCES Evaluations(Id);ALTER TABLE EvaluatorChangeHistory ADD CONSTRAINT FK_EvaluatorHistory_PreviousEvaluator FOREIGN KEY(PreviousEvaluatorId) REFERENCES Employees(Id);ALTER TABLE EvaluatorChangeHistory ADD CONSTRAINT FK_EvaluatorHistory_NewEvaluator FOREIGN KEY(NewEvaluatorId) REFERENCES Employees(Id);ALTER TABLE EvaluatorChangeHistory ADD CONSTRAINT FK_EvaluatorHistory_ChangedBy FOREIGN KEY(ChangedBy) REFERENCES Employees(Id);
ALTER TABLE AuditLogs ADD CONSTRAINT FK_AuditLog_User FOREIGN KEY(UserId) REFERENCES AppUsers(Id);